<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class Order extends Model {protected $fillable=['order_number','customer_id','branch_id','address_id','fulfillment_type','status','payment_status','scheduled_at','subtotal','discount_total','tax_total','delivery_fee','grand_total','notes','placed_at']; protected $casts=['scheduled_at'=>'datetime','placed_at'=>'datetime','subtotal'=>'decimal:2','discount_total'=>'decimal:2','tax_total'=>'decimal:2','delivery_fee'=>'decimal:2','grand_total'=>'decimal:2']; public function items(){return $this->hasMany(OrderItem::class);} public function customer(){return $this->belongsTo(User::class,'customer_id');} public function branch(){return $this->belongsTo(Branch::class);} public function address(){return $this->belongsTo(Address::class);} public function payment(){return $this->hasOne(Payment::class);} public function assignment(){return $this->hasOne(DeliveryAssignment::class);}
 public function statusHistory(){return $this->hasMany(OrderStatusHistory::class)->latest();} public function scopeActive($q){return $q->whereNotIn('status',['delivered','cancelled','completed']);}}